def butir_untuk(pilihan: set[str], jenis: set[str] | None = None) -> list[dict]:
    """Butir yang cocok dengan tool yang terpasang: semua `butuh` terpasang dan tidak ada `tanpa` yang terpasang."""
    return [b for b in BUTIR
            if set(b["butuh"]) <= pilihan and not (set(b.get("tanpa", ())) & pilihan) and (jenis is None or b["jenis"] in jenis)]


def butir_hampir(pilihan: set[str]) -> list[tuple[dict, set[str]]]:
    """Butir yang belum muncul tetapi hanya kurang satu tool: (butir, tool yang kurang)."""
    hasil = []
    for b in BUTIR:
        kurang = set(b["butuh"]) - pilihan
        if len(kurang) == 1 and not (set(b.get("tanpa", ())) & pilihan):
            hasil.append((b, kurang))
    return hasil
